class Mutex {
  constructor() {
    this.locked = false;
    this.queue = [];
  }

  acquire() {
    // TODO: return a Promise. If this.locked is false, set it to true and
    // resolve immediately. If it's already true, push the resolve function
    // onto this.queue instead of resolving yet.
  }

  release() {
    if (this.queue.length > 0) {
      const next = this.queue.shift();
      next();
    } else {
      this.locked = false;
    }
  }
}

